// Destinatarios de los formularios del sitio.
// Pendiente: agregar 'apadillar@iingen.unam.mx' cuando se confirme.
const DESTINATARIOS = ['jyes407@gmail.com'];

const b = $json.body || {};
const limpia = (v, max = 2000) => String(v ?? '').trim().slice(0, max);
const esc = (t) => t.replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const tipo = limpia(b.tipo, 20);
const correo = limpia(b.correo, 200);
const correoOk = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(correo);
const esBot = limpia(b.website, 200) !== '';

if (esBot || !correoOk || !['suscripcion', 'membresia'].includes(tipo)) {
  return [{ json: { valido: false, motivo: esBot ? 'trampa' : 'datos' } }];
}

const fecha = new Date(b.enviado || Date.now()).toLocaleString('es-MX', { timeZone: 'America/Mexico_City' });
const fila = (k, v) => v ? `<tr><td style="padding:8px 14px 8px 0;color:#5b6c61;font:600 12px Arial;text-transform:uppercase;letter-spacing:.08em;vertical-align:top;white-space:nowrap">${k}</td><td style="padding:8px 0;font:15px Arial;color:#0a1a12">${esc(v).replace(/\n/g, '<br>')}</td></tr>` : '';

let asunto, titulo, filas;
if (tipo === 'membresia') {
  const nombre = limpia(b.nombre, 200);
  asunto = `Nueva solicitud de membresía · ${nombre || correo}`;
  titulo = 'Nueva solicitud de membresía';
  filas = fila('Nombre', nombre) + fila('Correo', correo) + fila('Institución', limpia(b.institucion, 300)) + fila('Motivo', limpia(b.mensaje, 3000));
} else {
  asunto = `Nueva suscripción al boletín · ${correo}`;
  titulo = 'Nueva suscripción al boletín';
  filas = fila('Correo', correo);
}
filas += fila('Fecha', fecha) + fila('Página', limpia(b.pagina, 300));

const html = `<div style="max-width:560px;margin:0 auto;font-family:Arial,sans-serif">
  <div style="background:#0f3a23;color:#fff;padding:20px 24px;border-radius:8px 8px 0 0">
    <div style="font:700 11px Arial;letter-spacing:.2em;text-transform:uppercase;color:#8fbf9e">REMACV · Sitio web</div>
    <div style="font:700 20px Arial;margin-top:6px">${titulo}</div>
  </div>
  <div style="border:1px solid #e3e8e4;border-top:0;padding:18px 24px;border-radius:0 0 8px 8px">
    <table style="border-collapse:collapse;width:100%">${filas}</table>
    <p style="font:12px Arial;color:#738a7e;margin-top:18px">Responde a este correo para contestarle directamente a ${esc(correo)}.</p>
  </div>
</div>`;

return [{ json: { valido: true, para: DESTINATARIOS.join(', '), asunto, html, responderA: correo, tipo } }];
